const item = $json;
const title = String(item.title || '').trim();
const rawUrl = String(item.link || item.guid || '').trim();
const tracking = new Set(['utm_source', 'utm_medium', 'utm_campaign', 'utm_term', 'utm_content', 'fbclid', 'gclid']);
let sourceUrl = rawUrl;
try {
  const parsed = new URL(rawUrl);
  for (const key of [...parsed.searchParams.keys()]) { if (tracking.has(key.toLowerCase())) parsed.searchParams.delete(key); }
  parsed.hash = '';
  parsed.hostname = parsed.hostname.toLowerCase();
  if ((parsed.protocol === 'https:' && parsed.port === '443') || (parsed.protocol === 'http:' && parsed.port === '80')) parsed.port = '';
  parsed.pathname = parsed.pathname.replace(/\/{2,}/g, '/').replace(/\/$/, '') || '/';
  sourceUrl = parsed.toString();
} catch {}
const text = String(item.contentSnippet || item.content || item.description || '').replace(/\s+/g, ' ').trim();
return { json: { dedupe_key: sourceUrl || title.toLowerCase(), source: 'rss', source_title: title, source_url: sourceUrl, source_published_at: item.isoDate || item.pubDate || null, source_text: text.slice(0, 12000) } };

const value = String($json.source_url || '').trim();
const parts = value.split('://');
const scheme = parts.length === 2 ? parts[0].toLowerCase() : '';
const authority = parts.length === 2 ? (parts[1].split(/[?#]/)[0].split('/')[0] || '') : '';
const hostname = authority.replace(/:\d+$/, '').toLowerCase();
const valid = (scheme === 'http' || scheme === 'https') && !!hostname && hostname !== 'localhost' && hostname !== '127.0.0.1' && hostname !== '::1' && !hostname.endsWith('.localhost');
return { json: { ...$json, source_url_valid: valid, validation_error: valid ? '' : 'Only public http/https URLs are allowed' } };

const source = $('Validate source URL').item.json;
// Keep the local model request bounded: long pages make the small local model time out.
const articleText = String($json.article_text || source.source_text || '').trim();
return { json: { ...source, ...$json, article_text: articleText.slice(0, 12000), fetch_ok: $json.ok === true } };

const raw = typeof $json.text === 'string' ? $json.text.trim() : JSON.stringify($json);
let analysis = null;
let parseError = '';
try { analysis = JSON.parse(raw); } catch (error) { parseError = 'AI returned invalid JSON'; }
const required = ['relevant', 'confidence', 'quality_score', 'reason', 'draft_title', 'draft_text', 'risks', 'suggested_tags'];
const isString = (value) => typeof value === 'string' && value.trim().length > 0;
const valid = !!analysis && typeof analysis === 'object' && !Array.isArray(analysis) && typeof analysis.relevant === 'boolean' && Number.isFinite(analysis.confidence) && analysis.confidence >= 0 && analysis.confidence <= 1 && Number.isFinite(analysis.quality_score) && analysis.quality_score >= 0 && analysis.quality_score <= 1 && isString(analysis.reason) && isString(analysis.draft_title) && isString(analysis.draft_text) && Array.isArray(analysis.risks) && analysis.risks.every(isString) && Array.isArray(analysis.suggested_tags) && analysis.suggested_tags.every(isString);
const reservedItems = $('Prepare reserved item').all();
const itemIndex = Number.isInteger($itemIndex) ? $itemIndex : 0;
const reserved = reservedItems[itemIndex]?.json || {};
const value = analysis || { relevant: false, confidence: 0, quality_score: 0, reason: '', draft_title: '', draft_text: '', risks: [], suggested_tags: [] };
const humanText = [value.reason, value.draft_title, value.draft_text].join(' ');
const letters = humanText.match(/[A-Za-zА-Яа-яІіЇїЄєҐґ]/g) || [];
const cyrillic = humanText.match(/[А-Яа-яІіЇїЄєҐґ]/g) || [];
const language_ok = letters.length > 0 && cyrillic.length / letters.length >= 0.45 && cyrillic.length >= 8;
return { json: { ...reserved, ...(valid ? value : {}), candidate_id: reserved.candidate_id, valid, validation_error: valid ? '' : (parseError || 'AI JSON structure is invalid'), raw_ai_output: raw.slice(0, 20000), language_ok, ai_model: 'local-main', raw_analysis: valid ? value : {} } };

const raw = typeof $json.text === 'string' ? $json.text.trim() : JSON.stringify($json);
let analysis = null;
try { analysis = JSON.parse(raw); } catch {}
const reservedItems = $('Prepare reserved item').all();
const itemIndex = Number.isInteger($itemIndex) ? $itemIndex : 0;
const original = reservedItems[itemIndex]?.json || {};
const isString = (value) => typeof value === 'string' && value.trim().length > 0;
const valid = !!analysis && typeof analysis === 'object' && !Array.isArray(analysis) && typeof analysis.relevant === 'boolean' && Number.isFinite(analysis.confidence) && analysis.confidence >= 0 && analysis.confidence <= 1 && Number.isFinite(analysis.quality_score) && analysis.quality_score >= 0 && analysis.quality_score <= 1 && isString(analysis.reason) && isString(analysis.draft_title) && isString(analysis.draft_text) && Array.isArray(analysis.risks) && analysis.risks.every(isString) && Array.isArray(analysis.suggested_tags) && analysis.suggested_tags.every(isString);
const value = analysis || { relevant: false, confidence: 0, quality_score: 0, reason: '', draft_title: '', draft_text: '', risks: [], suggested_tags: [] };
const humanText = [value.reason, value.draft_title, value.draft_text].join(' ');
const letters = humanText.match(/[A-Za-zА-Яа-яІіЇїЄєҐґ]/g) || [];
const cyrillic = humanText.match(/[А-Яа-яІіЇїЄєҐґ]/g) || [];
const language_ok = valid && letters.length > 0 && cyrillic.length / letters.length >= 0.45 && cyrillic.length >= 8;
return { json: { ...original, ...value, candidate_id: original.candidate_id, valid, validation_error: valid ? '' : 'Repaired AI JSON structure is invalid', raw_ai_output: raw.slice(0, 20000), language_ok, ai_model: 'local-main', raw_analysis: valid ? { ...value, repaired_once: true } : {} } };

const raw = typeof $json.text === 'string' ? $json.text.trim() : JSON.stringify($json);
let analysis = null;
try { analysis = JSON.parse(raw); } catch {}
const reservedItems = $('Prepare reserved item').all();
const itemIndex = Number.isInteger($itemIndex) ? $itemIndex : 0;
const original = reservedItems[itemIndex]?.json || {};
const isString = (value) => typeof value === 'string' && value.trim().length > 0;
const valid = !!analysis && typeof analysis === 'object' && !Array.isArray(analysis) && typeof analysis.relevant === 'boolean' && Number.isFinite(analysis.confidence) && analysis.confidence >= 0 && analysis.confidence <= 1 && Number.isFinite(analysis.quality_score) && analysis.quality_score >= 0 && analysis.quality_score <= 1 && isString(analysis.reason) && isString(analysis.draft_title) && isString(analysis.draft_text) && Array.isArray(analysis.risks) && Array.isArray(analysis.suggested_tags);
const value = analysis || { relevant: false, confidence: 0, quality_score: 0, reason: '', draft_title: '', draft_text: '', risks: [], suggested_tags: [] };
const humanText = [value.reason, value.draft_title, value.draft_text].join(' ');
const letters = humanText.match(/[A-Za-zА-Яа-яІіЇїЄєҐґ]/g) || [];
