const language_ok = valid && letters.length > 0 && cyrillic.length / letters.length >= 0.45 && cyrillic.length >= 8;
return { json: { ...original, ...value, candidate_id: original.candidate_id, valid, validation_error: valid ? '' : 'UA fallback JSON structure is invalid', language_ok, ai_model: 'local-main', raw_analysis: valid ? { ...value, translated_to_ukrainian: true } : {} } };

const confidence = Math.round(Number($json.confidence || 0) * 100);
const quality = Math.round(Number($json.quality_score || 0) * 100);
const candidateId = Number($json.candidate_id || $json.id || 0);
const sourceUrl = String($json.source_url || '');
const reason = String($json.reason || '').trim() || 'Причина не вказана';
const telegram_text = `📝 Кандидат #${candidateId}

${String($json.draft_title || '').trim()}

${String($json.draft_text || '').trim()}

📊 AI-оцінка
🎯 Впевненість: ${confidence}%
⭐ Якість: ${quality}%

💡 Причина:
${reason}

🔗 Джерело:
${sourceUrl}`;
const reply_markup = { inline_keyboard: [[{ text: '✅ Опублікувати', callback_data: 'approve:' + candidateId }, { text: '✏️ Правка', callback_data: 'edit:' + candidateId }], [{ text: '🔄 Перегенерувати', callback_data: 'regenerate:' + candidateId }, { text: '❌ Відхилити', callback_data: 'reject:' + candidateId }], [{ text: '🔗 Відкрити джерело', url: sourceUrl }]] };
return { json: { ...$json, telegram_text, reply_markup } };
